            ['term' => 'Safety Behaviors', 'definition' => 'Maladaptive behavioral actions (e.g., carrying water, requiring a companion, sitting near exits) performed to temporarily tolerate phobic situations.'],
            ['term' => 'Active Avoidance', 'definition' => 'Behavioral modification wherein an individual deliberately alters their routine to physically avoid encountering agoraphobic situations.'],
            ['term' => 'Incapacitating Symptoms', 'definition' => 'Physical or neurological symptoms (dizziness, fainting, loss of bowel/bladder control) that an individual fears will leave them helpless in public.']
