            ['term' => 'Applied Tension Technique', 'definition' => 'A behavioral therapy technique involving systematic muscle contraction to elevate blood pressure and prevent syncope in blood-injection-injury phobia.'],
            ['term' => 'Systematic Desensitization', 'definition' => 'A behavioral therapy combining relaxation training with graduated in vivo or imaginal exposure along a fear hierarchy.'],
